from flask import Flask, render_template
from .services import hello_logic, test_logic, result_logic

app = Flask(__name__)


@app.route('/')
def hello():
    return hello_logic()


@app.route('/test')
def test():
    return test_logic()


@app.route('/result')
def result():
    dict_data = {'phy': 50, 'che': 60, 'maths': 70}
    return render_template('result.html', result=dict_data)
